solution.solution.c:
#include <stdarg.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct { char *data; size_t len; size_t cap; } StrBuf;

static int sb_reserve(StrBuf *sb, size_t extra)
{
    size_t need = sb->len + extra + 1;
    if (need <= sb->cap) return 0;
    size_t cap = sb->cap ? sb->cap : 16;
    while (cap < need) cap *= 2;
    char *p = realloc(sb->data, cap);
    if (!p) return -1;
    if (!sb->data) p[0] = '\0';
    sb->data = p;
    sb->cap = cap;
    return 0;
}

int sb_append(StrBuf *sb, const char *text)
{
    size_t n = strlen(text);
    if (sb_reserve(sb, n) != 0) return -1;
    memcpy(sb->data + sb->len, text, n + 1);
    sb->len += n;
    return 0;
}

int sb_appendf(StrBuf *sb, const char *fmt, ...)
{
    va_list ap, copy;
    va_start(ap, fmt);
    va_copy(copy, ap);
    int n = vsnprintf(NULL, 0, fmt, copy);
    va_end(copy);
    if (n < 0 || sb_reserve(sb, (size_t)n) != 0) {
        va_end(ap);
        return -1;
    }
    vsnprintf(sb->data + sb->len, sb->cap - sb->len, fmt, ap);
    va_end(ap);
    sb->len += (size_t)n;
    return 0;
}

char *sb_take(StrBuf *sb)
{
    char *s = sb->data ? sb->data : calloc(1, 1);
    sb->data = NULL;
    sb->len = sb->cap = 0;
    return s;
}

void sb_free(StrBuf *sb)
{
    free(sb->data);
    sb->data = NULL;
    sb->len = sb->cap = 0;
}

unitTests:
TEST("appending grows the buffer") { StrBuf sb = {0}; for (int i = 0; i < 100; i++) CHECK_EQ(sb_append(&sb, "abc"), 0); CHECK_EQ((int)sb.len, 300); CHECK((int)sb.cap >= 301); CHECK_EQ((int)strlen(sb.data), 300); CHECK_EQ(sb.data[299], 'c'); sb_free(&sb); CHECK(sb.data == NULL); }
TEST("formatted appends") { StrBuf sb = {0}; sb_appendf(&sb, "%s=%d", "x", 42); sb_appendf(&sb, ", %.1f%%", 99.5); CHECK_STR(sb.data, "x=42, 99.5%"); CHECK_EQ((int)sb.len, 11); sb_free(&sb); }
TEST("a long formatted append") { StrBuf sb = {0}; sb_append(&sb, ">"); sb_appendf(&sb, "%0200d", 7); CHECK_EQ((int)sb.len, 201); CHECK_EQ(sb.data[200], '7'); sb_free(&sb); }
TEST("take hands over and resets") { StrBuf sb = {0}; sb_append(&sb, "hello"); char *s = sb_take(&sb); CHECK_STR(s, "hello"); CHECK(sb.data == NULL); CHECK_EQ((int)sb.len, 0); free(s); char *e = sb_take(&sb); CHECK(e != NULL); CHECK_STR(e, ""); free(e); }

